#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = AppCore

    public static func lift(_ handle: UInt64) throws -> AppCore {
        return AppCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: AppCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: AppCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAppCore_lift(_ handle: UInt64) throws -> AppCore {
    return try FfiConverterTypeAppCore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAppCore_lower(_ value: AppCore) -> UInt64 {
    return FfiConverterTypeAppCore.lower(value)
}






/**
 * One consumer's events. Await `next()` in a loop; `None` means it ended.
 */
public protocol AppEventsProtocol: AnyObject, Sendable {
    
    /**
     * Ends this stream; a pending `next()` returns `None`.
     */
    func cancel() 
    
    /**
     * The next event, or `None` once this stream has ended.
     */
    func next() async  -> AppEvent?
    
}
